import * as THREE from 'three';
// Pin the grade once at init; later iterations change materials, never these numbers.
export function pinGrade(renderer, scene, mode = 'exterior') {
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = mode === 'dark-interior' ? 0.35 : 0.7;   // 0.6-0.8 exterior, ~0.35 interior
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  const hemi = scene.getObjectByName('hemi') || new THREE.HemisphereLight(0x9fb3c8, 0x2a2622, 0.7);
  hemi.name = 'hemi';
  hemi.intensity = mode === 'dark-interior' ? 0.05 : 0.7;                 // near-black is the interior target, not moody grey
  scene.add(hemi);
}
// Self-check right after renderer.render(): measure the band before submitting the iteration.
export function measureGrade(renderer) {
  const gl = renderer.getContext();
  const w = gl.drawingBufferWidth, h = gl.drawingBufferHeight, n = w * h;
  const px = new Uint8Array(n * 4);
  gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, px);
  let sum = 0, above = 0, below = 0;
  for (let i = 0; i < px.length; i += 4) {
    const l = (0.2126 * px[i] + 0.7152 * px[i + 1] + 0.0722 * px[i + 2]) / 255;
    sum += l; if (l > 0.9) above++; if (l < 0.06) below++;
  }
  const mean = sum / n;
  return { mean, above: above / n, below: below / n, ok: mean >= 0.32 && mean <= 0.45 && above / n <= 0.02 && below / n >= 0.05 };
}
